-- PILO 0.2: immutable 0001 retained; additive workspace contracts.
CREATE TABLE SpaceGeneration(space_id TEXT PRIMARY KEY REFERENCES KnowledgeSpace,source_generation INTEGER NOT NULL DEFAULT 0,indexed_generation INTEGER NOT NULL DEFAULT 0,CHECK(indexed_generation BETWEEN 0 AND source_generation)) STRICT;
INSERT INTO SpaceGeneration(space_id) SELECT space_id FROM KnowledgeSpace;
CREATE TRIGGER space_generation_seed AFTER INSERT ON KnowledgeSpace BEGIN INSERT INTO SpaceGeneration(space_id) VALUES(NEW.space_id); END;
CREATE TABLE ContentUnit(unit_id TEXT PRIMARY KEY,space_id TEXT NOT NULL,revision_id TEXT,knowledge_version_id TEXT,ordinal INTEGER NOT NULL CHECK(ordinal>=0),text TEXT NOT NULL,content_hash TEXT NOT NULL,UNIQUE(space_id,unit_id),UNIQUE(revision_id,ordinal),UNIQUE(knowledge_version_id,ordinal),CHECK((revision_id IS NOT NULL)+(knowledge_version_id IS NOT NULL)=1),FOREIGN KEY(space_id,revision_id) REFERENCES FileRevision(space_id,revision_id),FOREIGN KEY(space_id,knowledge_version_id) REFERENCES KnowledgeVersion(space_id,version_id)) STRICT;
CREATE VIRTUAL TABLE ContentFTS USING fts5(text,content='ContentUnit',content_rowid='rowid',tokenize='trigram');
CREATE TRIGGER content_fts_insert AFTER INSERT ON ContentUnit BEGIN INSERT INTO ContentFTS(rowid,text) VALUES(NEW.rowid,NEW.text); END;
CREATE TABLE RetrievalRun(retrieval_id TEXT PRIMARY KEY,execution_id TEXT NOT NULL REFERENCES Execution,project_id TEXT NOT NULL REFERENCES Project,principal_id TEXT NOT NULL REFERENCES Principal,request_hash TEXT NOT NULL,idempotency_key TEXT NOT NULL,scope_fingerprint TEXT NOT NULL,policy_version TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('COMPLETED','PARTIAL')),sufficiency TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(execution_id,retrieval_id),UNIQUE(execution_id,idempotency_key)) STRICT;
CREATE TABLE RetrievalCandidate(retrieval_id TEXT NOT NULL REFERENCES RetrievalRun,unit_id TEXT NOT NULL REFERENCES ContentUnit,rank_position INTEGER NOT NULL CHECK(rank_position>0),candidate_status TEXT NOT NULL CHECK(candidate_status IN('SELECTED','EXCLUDED')),reason TEXT NOT NULL,PRIMARY KEY(retrieval_id,unit_id)) STRICT;
CREATE TABLE ContextSnapshot(snapshot_id TEXT PRIMARY KEY,execution_id TEXT NOT NULL,retrieval_id TEXT NOT NULL,content_ref TEXT NOT NULL,context_hash TEXT NOT NULL,token_count INTEGER NOT NULL CHECK(token_count>=0),tokenizer_id TEXT NOT NULL,assembly_policy_version TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(execution_id,snapshot_id),FOREIGN KEY(execution_id,retrieval_id) REFERENCES RetrievalRun(execution_id,retrieval_id)) STRICT;
CREATE TABLE ContextSnapshotItem(snapshot_id TEXT NOT NULL REFERENCES ContextSnapshot,ordinal INTEGER NOT NULL,space_id TEXT NOT NULL,unit_id TEXT NOT NULL,content_hash TEXT NOT NULL,PRIMARY KEY(snapshot_id,ordinal),FOREIGN KEY(space_id,unit_id) REFERENCES ContentUnit(space_id,unit_id)) STRICT;
ALTER TABLE ModelInvocation ADD COLUMN context_snapshot_id TEXT REFERENCES ContextSnapshot(snapshot_id);
CREATE TRIGGER model_context_insert BEFORE INSERT ON ModelInvocation WHEN NEW.context_snapshot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ContextSnapshot WHERE snapshot_id=NEW.context_snapshot_id AND execution_id=NEW.execution_id) BEGIN SELECT RAISE(ABORT,'Model context execution mismatch'); END;
CREATE TRIGGER model_context_update BEFORE UPDATE OF context_snapshot_id,execution_id ON ModelInvocation WHEN NEW.context_snapshot_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM ContextSnapshot WHERE snapshot_id=NEW.context_snapshot_id AND execution_id=NEW.execution_id) BEGIN SELECT RAISE(ABORT,'Model context execution mismatch'); END;
CREATE TABLE QueryCache(cache_key TEXT PRIMARY KEY,scope_fingerprint TEXT NOT NULL,policy_version TEXT NOT NULL,candidates TEXT NOT NULL CHECK(json_valid(candidates)),created_at TEXT NOT NULL) STRICT;
CREATE TABLE CacheDependency(cache_key TEXT NOT NULL REFERENCES QueryCache ON DELETE CASCADE,space_id TEXT NOT NULL REFERENCES SpaceGeneration,source_generation INTEGER NOT NULL,indexed_generation INTEGER NOT NULL,PRIMARY KEY(cache_key,space_id)) STRICT;
CREATE TABLE ResourceRegistry(resource_id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES KnowledgeSpace,revision_id TEXT,knowledge_version_id TEXT,content_ref TEXT NOT NULL,content_hash TEXT NOT NULL,CHECK((revision_id IS NOT NULL)+(knowledge_version_id IS NOT NULL)=1),FOREIGN KEY(space_id,revision_id) REFERENCES FileRevision(space_id,revision_id),FOREIGN KEY(space_id,knowledge_version_id) REFERENCES KnowledgeVersion(space_id,version_id)) STRICT;
CREATE TABLE MemoryReference(memory_id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES KnowledgeSpace,resource_id TEXT NOT NULL REFERENCES ResourceRegistry,conditions TEXT NOT NULL CHECK(json_valid(conditions))) STRICT;
CREATE TRIGGER memory_scope BEFORE INSERT ON MemoryReference WHEN NOT EXISTS(SELECT 1 FROM ResourceRegistry WHERE resource_id=NEW.resource_id AND space_id=NEW.space_id) BEGIN SELECT RAISE(ABORT,'Memory scope mismatch'); END;
CREATE TABLE SkillDefinition(skill_id TEXT NOT NULL,version TEXT NOT NULL,manifest TEXT NOT NULL CHECK(json_valid(manifest)),manifest_hash TEXT NOT NULL,implementation_hash TEXT NOT NULL,approved_by TEXT NOT NULL REFERENCES Principal,created_at TEXT NOT NULL,PRIMARY KEY(skill_id,version)) STRICT;
CREATE TABLE ExecutionPlan(plan_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES Project,plan_hash TEXT NOT NULL,definition TEXT NOT NULL CHECK(json_valid(definition)),created_at TEXT NOT NULL) STRICT;
CREATE TABLE ExecutionPlanBinding(execution_id TEXT PRIMARY KEY REFERENCES Execution,plan_id TEXT NOT NULL REFERENCES ExecutionPlan) STRICT;
CREATE TABLE ExecutionSkillBinding(step_id TEXT PRIMARY KEY REFERENCES ExecutionStep,skill_id TEXT NOT NULL,skill_version TEXT NOT NULL,manifest_hash TEXT NOT NULL,input_json TEXT NOT NULL CHECK(json_valid(input_json)),FOREIGN KEY(skill_id,skill_version) REFERENCES SkillDefinition(skill_id,version)) STRICT;
-- Queue state is distinct from the immutable 0001 execution step status enum.
CREATE TABLE StepScheduling(step_id TEXT PRIMARY KEY REFERENCES ExecutionStep,queue_state TEXT NOT NULL CHECK(queue_state IN('PENDING','BLOCKED','READY','RUNNING','WAITING_APPROVAL','RETRY_WAIT','COMPLETED','FAILED','CANCELLED','SKIPPED')),attempt_number INTEGER NOT NULL DEFAULT 0,fencing_token INTEGER NOT NULL DEFAULT 0,lease_owner TEXT,lease_expires_at REAL,next_attempt_at REAL NOT NULL DEFAULT 0) STRICT;
CREATE TABLE StepAttempt(attempt_id TEXT PRIMARY KEY,step_id TEXT NOT NULL REFERENCES ExecutionStep,attempt_number INTEGER NOT NULL,fencing_token INTEGER NOT NULL,worker_id TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('RUNNING','COMPLETED','FAILED','INTERRUPTED','CANCELLED')),input_hash TEXT NOT NULL,output_ref TEXT,error_code TEXT,started_at TEXT NOT NULL,finished_at TEXT,UNIQUE(step_id,attempt_number)) STRICT;
CREATE TABLE ResourceReservation(attempt_id TEXT PRIMARY KEY REFERENCES StepAttempt,resource_class TEXT NOT NULL,lease_expires_at REAL NOT NULL,released_at TEXT) STRICT;
CREATE TRIGGER dependency_cycle BEFORE INSERT ON ExecutionStepDependency WHEN EXISTS(WITH RECURSIVE reachable(id) AS(SELECT NEW.depends_on_step_id UNION SELECT d.depends_on_step_id FROM ExecutionStepDependency d JOIN reachable r ON d.step_id=r.id WHERE d.execution_id=NEW.execution_id) SELECT 1 FROM reachable WHERE id=NEW.step_id) BEGIN SELECT RAISE(ABORT,'DAG cycle'); END;
CREATE TRIGGER dependency_frozen_update BEFORE UPDATE ON ExecutionStepDependency BEGIN SELECT RAISE(ABORT,'Dependency immutable'); END;
CREATE TRIGGER dependency_plan_frozen BEFORE INSERT ON ExecutionStepDependency WHEN EXISTS(SELECT 1 FROM ExecutionPlanBinding WHERE execution_id=NEW.execution_id) BEGIN SELECT RAISE(ABORT,'Plan immutable'); END;
CREATE TRIGGER dependency_frozen_delete BEFORE DELETE ON ExecutionStepDependency WHEN EXISTS(SELECT 1 FROM ExecutionPlanBinding WHERE execution_id=OLD.execution_id) BEGIN SELECT RAISE(ABORT,'Plan immutable'); END;
CREATE TRIGGER step_transition BEFORE UPDATE OF status ON ExecutionStep WHEN NEW.status<>OLD.status AND NOT((OLD.status IN('PENDING','READY','WAITING_APPROVAL') AND NEW.status IN('READY','RUNNING','WAITING_APPROVAL','CANCELLED','SKIPPED','FAILED')) OR (OLD.status='RUNNING' AND NEW.status IN('READY','COMPLETED','FAILED','CANCELLED'))) BEGIN SELECT RAISE(ABORT,'Invalid step transition'); END;
CREATE TRIGGER step_plan_insert BEFORE INSERT ON ExecutionStep WHEN EXISTS(SELECT 1 FROM ExecutionPlanBinding WHERE execution_id=NEW.execution_id) BEGIN SELECT RAISE(ABORT,'Plan immutable'); END;
CREATE TRIGGER step_plan_update BEFORE UPDATE OF execution_id,step_number,step_key,step_type,input_ref ON ExecutionStep WHEN EXISTS(SELECT 1 FROM ExecutionPlanBinding WHERE execution_id=OLD.execution_id) BEGIN SELECT RAISE(ABORT,'Plan immutable'); END;
CREATE TABLE Checkpoint(checkpoint_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES Project,manifest_ref TEXT NOT NULL,manifest_hash TEXT NOT NULL,git_commit TEXT NOT NULL,created_by TEXT NOT NULL REFERENCES Principal,created_at TEXT NOT NULL,UNIQUE(project_id,checkpoint_id)) STRICT;
CREATE TABLE CheckpointItem(checkpoint_id TEXT NOT NULL REFERENCES Checkpoint,resource_id TEXT NOT NULL REFERENCES ResourceRegistry,PRIMARY KEY(checkpoint_id,resource_id)) STRICT;
CREATE TABLE RecoveryOperation(operation_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES Project,checkpoint_id TEXT NOT NULL,execution_id TEXT NOT NULL REFERENCES Execution,kind TEXT NOT NULL CHECK(kind IN('ROLLBACK','REPLAY','INDEX_ONLY')),plan_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('READY','RUNNING','INTERRUPTED','RECONCILING','VERIFYING','COMPLETED','FAILED')),phase TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(project_id,idempotency_key),FOREIGN KEY(project_id,checkpoint_id) REFERENCES Checkpoint(project_id,checkpoint_id)) STRICT;
CREATE TABLE RecoveryLease(project_id TEXT PRIMARY KEY REFERENCES Project,lease_owner TEXT,fencing_token INTEGER NOT NULL DEFAULT 0,lease_expires_at REAL NOT NULL DEFAULT 0) STRICT;
CREATE TABLE RecoveryVerification(operation_id TEXT PRIMARY KEY REFERENCES RecoveryOperation,result TEXT NOT NULL CHECK(json_valid(result)),created_at TEXT NOT NULL) STRICT;
CREATE TABLE ApprovalGrant(approval_id TEXT PRIMARY KEY REFERENCES ApprovalRequest,project_id TEXT REFERENCES Project,context_json TEXT NOT NULL CHECK(json_valid(context_json)),revoked_at TEXT) STRICT;
CREATE TABLE ErrorCase(case_id TEXT PRIMARY KEY,space_id TEXT NOT NULL REFERENCES KnowledgeSpace,status TEXT NOT NULL CHECK(status IN('OPEN','INVESTIGATING','RESOLVED','MONITORING','CLOSED')),created_at TEXT NOT NULL) STRICT;
CREATE TABLE ErrorFingerprint(case_id TEXT NOT NULL REFERENCES ErrorCase,fingerprint_version TEXT NOT NULL,fingerprint TEXT NOT NULL,PRIMARY KEY(case_id,fingerprint_version,fingerprint)) STRICT;
CREATE TABLE ErrorOccurrence(occurrence_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES ErrorCase,error_id TEXT NOT NULL REFERENCES ErrorRecord,environment TEXT NOT NULL CHECK(json_valid(environment)),created_at TEXT NOT NULL) STRICT;
CREATE TABLE ErrorResolution(resolution_id TEXT PRIMARY KEY,case_id TEXT NOT NULL REFERENCES ErrorCase,status TEXT NOT NULL CHECK(status IN('PROPOSED','TESTED','VERIFIED','REJECTED','SUPERSEDED')),description TEXT NOT NULL,evidence_ref TEXT,created_at TEXT NOT NULL) STRICT;
CREATE TABLE TraceSpan(span_id TEXT PRIMARY KEY,trace_id TEXT NOT NULL,parent_span_id TEXT REFERENCES TraceSpan,execution_id TEXT REFERENCES Execution,project_id TEXT REFERENCES Project,operation_name TEXT NOT NULL,duration_ms INTEGER NOT NULL CHECK(duration_ms>=0),status TEXT NOT NULL,details TEXT NOT NULL CHECK(json_valid(details)),created_at TEXT NOT NULL) STRICT;
CREATE TABLE DiagnosticRun(run_id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES Project,execution_id TEXT NOT NULL REFERENCES Execution,profile TEXT NOT NULL,status TEXT NOT NULL,result_ref TEXT NOT NULL,created_at TEXT NOT NULL) STRICT;
CREATE TABLE DecisionRecord(decision_id TEXT PRIMARY KEY,namespace TEXT NOT NULL,source_turn TEXT NOT NULL,status TEXT NOT NULL,decision TEXT NOT NULL,verification TEXT NOT NULL,implementation TEXT NOT NULL) STRICT;
CREATE TRIGGER immutable_ContentUnit_UPDATE BEFORE UPDATE ON ContentUnit BEGIN SELECT RAISE(ABORT,'Immutable ContentUnit'); END;
CREATE TRIGGER immutable_ContentUnit_DELETE BEFORE DELETE ON ContentUnit BEGIN SELECT RAISE(ABORT,'Immutable ContentUnit'); END;
CREATE TRIGGER immutable_RetrievalRun_UPDATE BEFORE UPDATE ON RetrievalRun BEGIN SELECT RAISE(ABORT,'Immutable RetrievalRun'); END;
CREATE TRIGGER immutable_RetrievalRun_DELETE BEFORE DELETE ON RetrievalRun BEGIN SELECT RAISE(ABORT,'Immutable RetrievalRun'); END;
CREATE TRIGGER immutable_RetrievalCandidate_UPDATE BEFORE UPDATE ON RetrievalCandidate BEGIN SELECT RAISE(ABORT,'Immutable RetrievalCandidate'); END;
CREATE TRIGGER immutable_RetrievalCandidate_DELETE BEFORE DELETE ON RetrievalCandidate BEGIN SELECT RAISE(ABORT,'Immutable RetrievalCandidate'); END;
CREATE TRIGGER immutable_ContextSnapshot_UPDATE BEFORE UPDATE ON ContextSnapshot BEGIN SELECT RAISE(ABORT,'Immutable ContextSnapshot'); END;
CREATE TRIGGER immutable_ContextSnapshot_DELETE BEFORE DELETE ON ContextSnapshot BEGIN SELECT RAISE(ABORT,'Immutable ContextSnapshot'); END;
CREATE TRIGGER immutable_ContextSnapshotItem_UPDATE BEFORE UPDATE ON ContextSnapshotItem BEGIN SELECT RAISE(ABORT,'Immutable ContextSnapshotItem'); END;
CREATE TRIGGER immutable_ContextSnapshotItem_DELETE BEFORE DELETE ON ContextSnapshotItem BEGIN SELECT RAISE(ABORT,'Immutable ContextSnapshotItem'); END;
CREATE TRIGGER immutable_ResourceRegistry_UPDATE BEFORE UPDATE ON ResourceRegistry BEGIN SELECT RAISE(ABORT,'Immutable ResourceRegistry'); END;
CREATE TRIGGER immutable_ResourceRegistry_DELETE BEFORE DELETE ON ResourceRegistry BEGIN SELECT RAISE(ABORT,'Immutable ResourceRegistry'); END;
CREATE TRIGGER immutable_SkillDefinition_UPDATE BEFORE UPDATE ON SkillDefinition BEGIN SELECT RAISE(ABORT,'Immutable SkillDefinition'); END;
CREATE TRIGGER immutable_SkillDefinition_DELETE BEFORE DELETE ON SkillDefinition BEGIN SELECT RAISE(ABORT,'Immutable SkillDefinition'); END;
CREATE TRIGGER immutable_ExecutionPlan_UPDATE BEFORE UPDATE ON ExecutionPlan BEGIN SELECT RAISE(ABORT,'Immutable ExecutionPlan'); END;
CREATE TRIGGER immutable_ExecutionPlan_DELETE BEFORE DELETE ON ExecutionPlan BEGIN SELECT RAISE(ABORT,'Immutable ExecutionPlan'); END;
CREATE TRIGGER immutable_ExecutionPlanBinding_UPDATE BEFORE UPDATE ON ExecutionPlanBinding BEGIN SELECT RAISE(ABORT,'Immutable ExecutionPlanBinding'); END;
CREATE TRIGGER immutable_ExecutionPlanBinding_DELETE BEFORE DELETE ON ExecutionPlanBinding BEGIN SELECT RAISE(ABORT,'Immutable ExecutionPlanBinding'); END;
CREATE TRIGGER immutable_ExecutionSkillBinding_UPDATE BEFORE UPDATE ON ExecutionSkillBinding BEGIN SELECT RAISE(ABORT,'Immutable ExecutionSkillBinding'); END;
CREATE TRIGGER immutable_ExecutionSkillBinding_DELETE BEFORE DELETE ON ExecutionSkillBinding BEGIN SELECT RAISE(ABORT,'Immutable ExecutionSkillBinding'); END;
CREATE TRIGGER immutable_Checkpoint_UPDATE BEFORE UPDATE ON Checkpoint BEGIN SELECT RAISE(ABORT,'Immutable Checkpoint'); END;
CREATE TRIGGER immutable_Checkpoint_DELETE BEFORE DELETE ON Checkpoint BEGIN SELECT RAISE(ABORT,'Immutable Checkpoint'); END;
CREATE TRIGGER immutable_CheckpointItem_UPDATE BEFORE UPDATE ON CheckpointItem BEGIN SELECT RAISE(ABORT,'Immutable CheckpointItem'); END;
CREATE TRIGGER immutable_CheckpointItem_DELETE BEFORE DELETE ON CheckpointItem BEGIN SELECT RAISE(ABORT,'Immutable CheckpointItem'); END;
CREATE TRIGGER immutable_RecoveryVerification_UPDATE BEFORE UPDATE ON RecoveryVerification BEGIN SELECT RAISE(ABORT,'Immutable RecoveryVerification'); END;
CREATE TRIGGER immutable_RecoveryVerification_DELETE BEFORE DELETE ON RecoveryVerification BEGIN SELECT RAISE(ABORT,'Immutable RecoveryVerification'); END;
CREATE TRIGGER immutable_ErrorOccurrence_UPDATE BEFORE UPDATE ON ErrorOccurrence BEGIN SELECT RAISE(ABORT,'Immutable ErrorOccurrence'); END;
CREATE TRIGGER immutable_ErrorOccurrence_DELETE BEFORE DELETE ON ErrorOccurrence BEGIN SELECT RAISE(ABORT,'Immutable ErrorOccurrence'); END;
CREATE TRIGGER immutable_TraceSpan_UPDATE BEFORE UPDATE ON TraceSpan BEGIN SELECT RAISE(ABORT,'Immutable TraceSpan'); END;
CREATE TRIGGER immutable_TraceSpan_DELETE BEFORE DELETE ON TraceSpan BEGIN SELECT RAISE(ABORT,'Immutable TraceSpan'); END;
CREATE TRIGGER immutable_DiagnosticRun_UPDATE BEFORE UPDATE ON DiagnosticRun BEGIN SELECT RAISE(ABORT,'Immutable DiagnosticRun'); END;
CREATE TRIGGER immutable_DiagnosticRun_DELETE BEFORE DELETE ON DiagnosticRun BEGIN SELECT RAISE(ABORT,'Immutable DiagnosticRun'); END;
CREATE TABLE SnapshotSeal(snapshot_id TEXT PRIMARY KEY REFERENCES ContextSnapshot) STRICT;
CREATE TRIGGER snapshot_item_sealed BEFORE INSERT ON ContextSnapshotItem WHEN EXISTS(SELECT 1 FROM SnapshotSeal WHERE snapshot_id=NEW.snapshot_id) BEGIN SELECT RAISE(ABORT,'Snapshot sealed'); END;
CREATE TRIGGER candidate_sealed BEFORE INSERT ON RetrievalCandidate WHEN EXISTS(SELECT 1 FROM ContextSnapshot s JOIN SnapshotSeal z USING(snapshot_id) WHERE s.retrieval_id=NEW.retrieval_id) BEGIN SELECT RAISE(ABORT,'Retrieval sealed'); END;
CREATE TRIGGER seal_update BEFORE UPDATE ON SnapshotSeal BEGIN SELECT RAISE(ABORT,'Seal immutable'); END;
CREATE TRIGGER seal_delete BEFORE DELETE ON SnapshotSeal BEGIN SELECT RAISE(ABORT,'Seal immutable'); END;
CREATE TABLE CheckpointSeal(checkpoint_id TEXT PRIMARY KEY REFERENCES Checkpoint) STRICT;
CREATE TRIGGER checkpoint_item_sealed BEFORE INSERT ON CheckpointItem WHEN EXISTS(SELECT 1 FROM CheckpointSeal WHERE checkpoint_id=NEW.checkpoint_id) BEGIN SELECT RAISE(ABORT,'Checkpoint sealed'); END;
CREATE TRIGGER cpseal_update BEFORE UPDATE ON CheckpointSeal BEGIN SELECT RAISE(ABORT,'Seal immutable'); END;
CREATE TRIGGER cpseal_delete BEFORE DELETE ON CheckpointSeal BEGIN SELECT RAISE(ABORT,'Seal immutable'); END;
CREATE TRIGGER registry_target BEFORE INSERT ON ResourceRegistry WHEN (NEW.revision_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM FileRevision WHERE revision_id=NEW.revision_id AND content_hash=NEW.content_hash AND storage_ref=NEW.content_ref)) OR (NEW.knowledge_version_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM KnowledgeVersion WHERE version_id=NEW.knowledge_version_id AND content_hash=NEW.content_hash AND content_ref=NEW.content_ref AND review_status='APPROVED')) BEGIN SELECT RAISE(ABORT,'Registry target mismatch'); END;
CREATE TRIGGER model_context_required BEFORE INSERT ON ModelInvocation WHEN NEW.context_snapshot_id IS NULL BEGIN SELECT RAISE(ABORT,'Model context required'); END;
CREATE TABLE ResolvedKnowledgeReference(execution_id TEXT NOT NULL REFERENCES Execution,reference_id TEXT NOT NULL REFERENCES KnowledgeReference,version_id TEXT NOT NULL REFERENCES KnowledgeVersion,resolved_at TEXT NOT NULL,PRIMARY KEY(execution_id,reference_id)) STRICT;
CREATE TRIGGER resolved_ref_update BEFORE UPDATE ON ResolvedKnowledgeReference BEGIN SELECT RAISE(ABORT,'Resolved reference immutable'); END;
CREATE TRIGGER resolved_ref_delete BEFORE DELETE ON ResolvedKnowledgeReference BEGIN SELECT RAISE(ABORT,'Resolved reference immutable'); END;
