INSERT INTO DecisionRecord VALUES('NEW-S28-D-04','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','Preserve originals and previous versions','See release test evidence','0.2.0 module contract');
INSERT INTO DecisionRecord VALUES('NEW-S28-D-05','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','Change-driven incremental analysis','See release test evidence','0.2.0 module contract');
INSERT INTO DecisionRecord VALUES('NEW-S28-D-06','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','Manual analysis supplement','See release test evidence','0.2.0 module contract');
