INSERT INTO DecisionRecord VALUES('NEW-S28-D-08','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','COMMON/PROJECT separation','See release test evidence','0.2.0 module contract');
