INSERT INTO DecisionRecord VALUES('NEW-S28-D-10','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','Deterministic CODE automation first','See release test evidence','0.2.0 module contract');
INSERT INTO DecisionRecord VALUES('NEW-S28-D-11','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','Separate rollback, replay and rebuild','See release test evidence','0.2.0 module contract');
INSERT INTO DecisionRecord VALUES('NEW-S28-D-12','NEW-S28','83c41d40-94cd-4f25-add2-ec3d38f58f3b','RETAINED','Python + uv development environment','See release test evidence','0.2.0 module contract');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-01','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','Keep applied ExecutionStep enum; represent BLOCKED/RETRY_WAIT in StepScheduling queue state.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-02','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','Recursive SQL cycle trigger plus service validation, immutable plan binding and terminal transition guard.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-03','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','ModelInvocation.context_snapshot_id and same-execution guards; new calls require a snapshot.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-04','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','HIST-ATLAS and NEW-S28 namespaces; ADR numbers here are PILO-IMPL IDs, not reuse of the illustrative ADR-0001.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-05','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','Typed ResourceRegistry limited to same-space immutable FileRevision/approved KnowledgeVersion; generic approval resources are action-specific canonical contexts.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-06','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','Memory stores references/conditions; Recovery reuses Execution but keeps separate policy/lease/verification coordinator; clean Git only.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-07','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','One additive atomic 0002 for the bounded MVP with pinned checksum and two-version Core validation; applied 0001 never edited.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-08','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','Retain historical event versions; current state is an addendum and deployment report, not mutation of SchemaMigration history.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
INSERT INTO DecisionRecord VALUES('PILO-IMPL-F-09','PILO-IMPL','eabc003d-ce16-4093-ade6-0a473f71f4b5','IMPLEMENTED','Current RBAC/policy/approval gates, COMMON promotion redaction/lineage suppression and fixed-identity stdio adapter.','See REQUIREMENTS_TRACEABILITY.md','Core 0.2.0/schema 2');
